"use client";

import type { ComponentProps, ReactNode } from "react";
import { DownloadIcon } from "lucide-react";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";
import { formatFileSize } from "@dimah-s3/core";
import type { FetchDownloadHooks } from "@dimah-s3/react";
import type { S3Api } from "@dimah-s3/core";
import { useTranslations } from "@fuma-translate/react";
import { useFetchDownload } from "@dimah-s3/react";
import { resolveStatusSlot, type StatusSlot } from "@/registry/dimah-s3-ui/lib/status-slot";
import { Button } from "@/registry/dimah-s3-ui/components/ui/button";
import { StatusAttachment } from "@/registry/dimah-s3-ui/components/dimah-s3/status-attachment";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/registry/dimah-s3-ui/components/ui/tooltip";
import { useDownloadToast } from "@/registry/dimah-s3-ui/hooks/use-download-toast";

/** Props for {@link ProgressDownloadButton}. */
export type ProgressDownloadButtonProps = FetchDownloadHooks & {
  /** S3Api. Optional when an `<S3Provider>` is present in the tree. */
  api?: S3Api;
  /** S3 object key to download. */
  objectKey: string;
  /** Download filename for Content-Disposition. */
  fileName?: string;
  /** Total file size in bytes (used for progress display). */
  fileSize?: number;
  /** Target bucket (overrides server default). */
  bucket?: string;
  /** Button label. */
  label?: string;
  /** Custom button content. Replaces default icon + label / progress text. */
  children?: ReactNode;
  className?: string;
  fillClassName?: string;
  disabled?: boolean;
  tooltipText?: string;
  /** Tooltip while downloading (click cancels). @default "Cancel download" */
  cancelTooltipText?: string;
  /** Show toasts during download. @default true */
  toast?: boolean;
  /**
   * Inline status control.
   * - `true` (default): render below the button
   * - `false`: hide status
   * - `(node) => ReactNode`: wrap or relocate the status node
   */
  status?: StatusSlot;
  /** Button variant. @default "outline" */
  variant?: ComponentProps<typeof Button>["variant"];
  /** Button size. @default "default" */
  size?: ComponentProps<typeof Button>["size"];
  /** Extra classes on the trigger button element. */
  buttonClassName?: string;
};

export function ProgressDownloadButton({
  api,
  objectKey,
  fileName,
  fileSize,
  bucket,
  label,
  children,
  className,
  fillClassName,
  disabled,
  tooltipText,
  cancelTooltipText,
  toast: enableToast = true,
  status: statusSlot = true,
  variant = "outline",
  size = "default",
  buttonClassName,
  beforeDownload,
  onDownloadStart,
  onProgress,
  onSuccess,
  onError,
  onCancel,
}: ProgressDownloadButtonProps) {
  const t = useTranslations();
  const toastHandlers = useDownloadToast({
    enabled: enableToast,
    objectKey,
    fileName,
    fileSize,
  });

  const dl = useFetchDownload({
    api,
    bucket,
    beforeDownload,
    onDownloadStart,
    onProgress,
    onSuccess: (key, actualFileName) => {
      toastHandlers.onSuccess(key, actualFileName);
      onSuccess?.(key, actualFileName);
    },
    onError: (key, error, phase) => {
      toastHandlers.onErrorWithPhase(key, error, phase);
      onError?.(key, error, phase);
    },
    onCancel: (key) => {
      toastHandlers.onCancel(key);
      onCancel?.(key);
    },
  });

  const isDownloading = dl.phase === "downloading" || dl.phase === "presigning";

  const handleClick = () => {
    if (isDownloading) {
      dl.cancel();
      return;
    }
    dl.download(objectKey, fileName);
  };

  const computedPercentFromFileSize =
    fileSize && fileSize > 0
      ? Math.min(100, Math.round((dl.progress.loaded / fileSize) * 100))
      : null;

  const fillPercent =
    dl.phase === "presigning"
      ? 12
      : dl.progress.total > 0
        ? dl.progress.percent
        : computedPercentFromFileSize;

  const isIndeterminateFill =
    isDownloading && fillPercent == null && dl.phase === "downloading";

  const buttonContent = children ?? (
    <>
      {!isDownloading && <DownloadIcon data-icon="inline-start" />}
      {isDownloading
        ? formatFileSize(dl.progress.loaded)
        : (label ?? t("Download", { note: "button" }))}
    </>
  );

  const statusNode =
    dl.phase === "error" ? (
      <StatusAttachment
        state="error"
        title={t("Download failed", { note: "status" })}
        description={dl.error ?? undefined}
      />
    ) : null;

  return (
    <div className={cn("inline-flex flex-col items-center gap-2", className)}>
      <Tooltip>
        <TooltipTrigger
          render={
            <Button
              variant={variant}
              size={size}
              disabled={disabled}
              className={cn(
                "relative min-w-24 overflow-hidden",
                buttonClassName,
              )}
              onClick={handleClick}
            />
          }
        >
          {isDownloading && (
            <span
              className={cn(
                "absolute inset-y-0 start-0 bg-primary/15",
                fillPercent != null
                  ? "transition-[width] duration-200"
                  : "w-full animate-pulse",
                fillClassName,
              )}
              style={
                fillPercent != null ? { width: `${fillPercent}%` } : undefined
              }
              aria-hidden={isIndeterminateFill}
            />
          )}
          <span className="relative z-10 flex w-full items-center justify-center gap-1">
            {buttonContent}
          </span>
        </TooltipTrigger>
        <TooltipContent>
          {isDownloading
            ? (cancelTooltipText ?? t("Cancel download", { note: "tooltip" }))
            : (tooltipText ?? t("Download file", { note: "tooltip" }))}
        </TooltipContent>
      </Tooltip>

      {resolveStatusSlot(statusSlot, statusNode)}
    </div>
  );
}

"use client";

import { formatFileSize, truncateFileName } from "@dimah-s3/core";
import { useTranslations } from "@fuma-translate/react";
import { useFormatDimahError } from "@dimah-s3/react";

import { toast } from "@/components/ui/toast";

export type DownloadToastOptions = {
  enabled?: boolean;
  objectKey: string;
  fileName?: string;
  fileSize?: number;
};

export function useDownloadToast({
  enabled = true,
  objectKey,
  fileName,
  fileSize,
}: DownloadToastOptions) {
  const t = useTranslations();
  const formatDimahError = useFormatDimahError();
  const displayName = fileName ?? objectKey.split("/").pop() ?? objectKey;

  const errorNode = (error: unknown) => (
    <span dir="auto" className="block [overflow-wrap:anywhere]">
      {formatDimahError(error)}
    </span>
  );

  const onInitiated = () => {
    if (enabled) {
      toast.add({
        type: "success",
        title: t("Download started", { note: "toast" }),
      });
    }
  };

  const onSuccess = (_key: string, actualFileName: string) => {
    if (!enabled) return;
    toast.close(`dl-${objectKey}`);
    toast.add({
      type: "success",
      title: t("Download complete", { note: "toast" }),
      description: (
        <span className="block">
          <bdi>{truncateFileName(actualFileName)}</bdi>
          {fileSize != null ? (
            <>
              {" "}
              ·{" "}
              <span
                dir="ltr"
                className="inline-block whitespace-nowrap tabular-nums"
              >
                {formatFileSize(fileSize)}
              </span>
            </>
          ) : null}
        </span>
      ),
    });
  };

  const onError = (_key: string, error: unknown) => {
    if (!enabled) return;
    toast.close(`dl-${objectKey}`);
    toast.add({
      type: "error",
      title: t("Download failed", { note: "toast" }),
      description: errorNode(error),
    });
  };

  const onErrorWithPhase = (_key: string, error: unknown, _phase: string) => {
    if (!enabled) return;
    toast.close(`dl-${objectKey}`);
    toast.add({
      type: "error",
      title: t("Download failed", { note: "toast" }),
      description: errorNode(error),
    });
  };

  const onCancel = (_key: string) => {
    if (!enabled) return;
    toast.close(`dl-${objectKey}`);
    toast.add({
      type: "info",
      title: t("Download cancelled", { note: "toast" }),
      description: <span dir="auto">{truncateFileName(displayName)}</span>,
    });
  };

  return { onInitiated, onSuccess, onError, onErrorWithPhase, onCancel };
}

"use client";

import type { ReactNode } from "react";
import {
  AlertCircleIcon,
  CheckCircleIcon,
  LoaderCircleIcon,
} from "lucide-react";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";
import {
  Attachment,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentMedia,
  AttachmentTitle,
} from "@/registry/dimah-s3-ui/components/ui/attachment";
import type { AttachmentState } from "@/registry/dimah-s3-ui/lib/attachment-state";

/** @deprecated Use {@link AttachmentState}. */
export type StatusAttachmentState = AttachmentState;

export type { AttachmentState };

export type StatusAttachmentProps = {
  state: AttachmentState;
  title?: ReactNode;
  description?: ReactNode;
  media?: ReactNode;
  actions?: ReactNode;
  className?: string;
};

/**
 * Minimal Attachment shell for operation feedback (upload/download/delete).
 * Relies on Attachment `data-state` styles for error/done chrome.
 */
export function StatusAttachment({
  state,
  title,
  description,
  media,
  actions,
  className,
}: StatusAttachmentProps) {
  const defaultMedia =
    state === "error" ? (
      <AlertCircleIcon />
    ) : state === "done" ? (
      <CheckCircleIcon />
    ) : state === "processing" || state === "uploading" ? (
      <LoaderCircleIcon className="animate-spin" data-slot="spinner" />
    ) : null;

  return (
    <Attachment
      state={state}
      size="sm"
      orientation="horizontal"
      className={cn("w-full max-w-full", className)}
    >
      <AttachmentMedia>{media ?? defaultMedia}</AttachmentMedia>
      <AttachmentContent>
        {title != null ? (
          <AttachmentTitle className="max-w-[48ch]">{title}</AttachmentTitle>
        ) : null}
        {description != null ? (
          <AttachmentDescription
            className={
              state === "error"
                ? "overflow-visible whitespace-normal [overflow-wrap:anywhere]"
                : undefined
            }
          >
            {description}
          </AttachmentDescription>
        ) : null}
      </AttachmentContent>
      {actions ? <AttachmentActions>{actions}</AttachmentActions> : null}
    </Attachment>
  );
}

import type { ReactNode } from "react";

/**
 * Controls inline status rendering for wired UI components.
 *
 * - `true` (default): render the status node in the default slot
 * - `false`: hide status
 * - `(node) => ReactNode`: wrap or relocate the status node
 */
export type StatusSlot = boolean | ((node: ReactNode) => ReactNode);

/** Resolve a {@link StatusSlot} against a built status node. */
export function resolveStatusSlot(
  slot: StatusSlot = true,
  node: ReactNode,
): ReactNode {
  if (slot === false) return null;
  if (typeof slot === "function") return slot(node);
  return node;
}

import type { ComponentProps } from "react";
import { Attachment } from "@/registry/dimah-s3-ui/components/ui/attachment";

/**
 * Attachment `state` values — derived from the stock shadcn {@link Attachment}
 * prop (do not edit `components/ui/attachment.tsx`).
 */
export type AttachmentState = NonNullable<
  ComponentProps<typeof Attachment>["state"]
>;

"use client";

import { FileIcon, defaultStyles } from "react-file-icon";
import type { DefaultExtensionType, FileIconProps } from "react-file-icon";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";

/**
 * Curated extensions with colored glyphs via `react-file-icon`.
 * Keep this list lean — duplicates and rare types belong in aliases / MIME
 * family fallbacks, not here. Unknown types use a neutral generic file icon.
 */
const CURATED_EXTS = [
  // documents
  "pdf",
  "doc",
  "docx",
  "txt",
  "md",
  // sheets / slides
  "xls",
  "xlsx",
  "csv",
  "ppt",
  "pptx",
  // archives
  "zip",
  "rar",
  "7z",
  "tar",
  "gz",
  // audio / video
  "mp3",
  "wav",
  "m4a",
  "mp4",
  "mov",
  "webm",
  "mkv",
  // images
  "png",
  "jpg",
  "gif",
  "webp",
  "svg",
  "heic",
  // code / data
  "json",
  "js",
  "ts",
  "jsx",
  "html",
  "css",
] as const;

type CuratedExt = (typeof CURATED_EXTS)[number];

const CURATED = new Set<string>(CURATED_EXTS);

/**
 * Map alternate extensions onto a curated key (same glyph, no list bloat).
 * Also remaps `defaultStyles` keys that differ from the real extension.
 */
const EXT_ALIASES: Record<string, CuratedExt | DefaultExtensionType> = {
  jpeg: "jpg",
  jpe: "jpg",
  "7zip": "7z",
  m4v: "mp4",
  aac: "m4a",
  flac: "mp3",
  ogg: "mp3",
  avi: "mp4",
  bmp: "png",
  tif: "png",
  tiff: "png",
};

/** `defaultStyles` lookup when the curated key differs from the library key. */
const STYLE_ALIASES: Record<string, DefaultExtensionType> = {
  "7z": "7zip",
};

const MIME_TO_EXT: Record<string, CuratedExt> = {
  "application/pdf": "pdf",
  "application/msword": "doc",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document":
    "docx",
  "application/vnd.ms-excel": "xls",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": "xlsx",
  "text/csv": "csv",
  "application/vnd.ms-powerpoint": "ppt",
  "application/vnd.openxmlformats-officedocument.presentationml.presentation":
    "pptx",
  "application/zip": "zip",
  "application/x-zip-compressed": "zip",
  "application/x-rar-compressed": "rar",
  "application/vnd.rar": "rar",
  "application/x-7z-compressed": "7z",
  "application/x-tar": "tar",
  "application/gzip": "gz",
  "audio/mpeg": "mp3",
  "audio/wav": "wav",
  "audio/mp4": "m4a",
  "audio/aac": "m4a",
  "video/mp4": "mp4",
  "video/quicktime": "mov",
  "video/webm": "webm",
  "video/x-matroska": "mkv",
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/gif": "gif",
  "image/webp": "webp",
  "image/svg+xml": "svg",
  "image/heic": "heic",
  "application/json": "json",
  "text/javascript": "js",
  "application/javascript": "js",
  "text/typescript": "ts",
  "application/typescript": "ts",
  "text/jsx": "jsx",
  "text/html": "html",
  "text/css": "css",
  "text/plain": "txt",
  "text/markdown": "md",
};

function extensionOf(fileName: string): string | null {
  const base = fileName.split(/[/\\]/).pop() ?? fileName;
  const dot = base.lastIndexOf(".");
  if (dot <= 0 || dot === base.length - 1) return null;
  return base.slice(dot + 1).toLowerCase();
}

function mimeFamilyExt(mime: string): CuratedExt | null {
  if (mime.startsWith("image/")) return "png";
  if (mime.startsWith("audio/")) return "mp3";
  if (mime.startsWith("video/")) return "mp4";
  if (mime.startsWith("text/")) return "txt";
  return null;
}

function normalizeExt(ext: string): CuratedExt | null {
  if (CURATED.has(ext)) return ext as CuratedExt;
  const aliased = EXT_ALIASES[ext];
  if (aliased && CURATED.has(aliased)) return aliased as CuratedExt;
  return null;
}

/** Resolve a curated extension key for icon styling (or `null` if unknown). */
export function resolveFileTypeExtension(
  fileName: string,
  mimeType?: string | null,
): string | null {
  const mime = mimeType?.trim().toLowerCase();
  if (mime) {
    const fromMime = MIME_TO_EXT[mime];
    if (fromMime) return fromMime;
    const family = mimeFamilyExt(mime);
    if (family) return family;
  }

  const ext = extensionOf(fileName);
  if (!ext) return null;
  return normalizeExt(ext);
}

function stylesFor(ext: string): Partial<FileIconProps> {
  const key = (STYLE_ALIASES[ext] ?? ext) as DefaultExtensionType;
  const fromDefaults = defaultStyles[key];
  if (fromDefaults) return fromDefaults;
  // `heic` may be missing from older @types; keep a sensible image style.
  if (ext === "heic") return { type: "image" };
  if (ext === "7z") return { type: "compressed" };
  return {};
}

export type FileTypeGlyphProps = {
  fileName: string;
  fileType?: string | null;
  className?: string;
};

/**
 * Colored file glyph for attachment media (no image preview).
 * Uses `react-file-icon` + a lean curated extension map.
 */
export function FileTypeGlyph({
  fileName,
  fileType,
  className,
}: FileTypeGlyphProps) {
  const ext = resolveFileTypeExtension(fileName, fileType);
  const label = ext ?? extensionOf(fileName) ?? undefined;
  const styles = ext ? stylesFor(ext) : { type: "document" as const };

  return (
    <span
      className={cn(
        // AttachmentMedia defaults bare SVGs to size-4; scale the glyph up
        // inside the existing media box without changing the slot.
        "flex size-full items-center justify-center [&_svg]:size-[1.4rem]!",
        className,
      )}
      aria-hidden
    >
      <FileIcon extension={label} {...styles} />
    </span>
  );
}
